/// <summary>
/// PaffH 12.12.24
/// set printJobSettings
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ProdParmStartUp, NDXSetupButtonProdProdIdent), FormControlEventType::Clicked)
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void NDXSetupButtonProdProdIdent_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    FormDataSource ProdParmStartUp_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(ProdParmStartUp, ProdParmStartUp));
    ProdParmStartUp prodParmStartUp = ProdParmStartUp_DS.cursor();

    SRSPrintDestinationSettings printJobSettings = new SRSPrintDestinationSettings(prodParmStartup.NDXSetupPrintProdProdIdent);
    SrsReportRunUtil::showSettingsDialog(printJobSettings);
    prodParmStartup.NDXSetupPrintProdProdIdent = printJobSettings.pack();
}

/// <summary>
/// PaffH 13.12.24
/// enable/disable Button printJobSettings
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ProdParmStartUp, ProdParmStartUp_NDXPrintProdProdIdent), FormControlEventType::Modified)
    ,SuppressBPWarning('BPParameterNotUsed','Parameter "e"')]
public static void ProdParmStartUp_NDXPrintProdProdIdent_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun thisFormRun = sender.formRun();
    FormDataSource ProdParmStartUp_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(ProdParmStartUp, ProdParmStartUp));
    ProdParmStartUp prodParmStartUp = ProdParmStartUp_ds.cursor();

    if (prodParmStartUp.NDXPrintProdProdIdent == NoYes::Yes)
    {
        if (!NDXProdIdentProcedureTable::findInventTable(prodParmStartUp.prodTable().inventTable().RecId))
        {
            warning(strfmt("@NDX:NDXItemWithPALabelDefinitionNotFound2", prodParmStartUp.prodTable().ItemId));
            prodParmStartUp.NDXPrintProdProdIdent = NoYes::No;
        }
    }

    thisFormRun.design().controlName(formControlStr(ProdParmStartUp, NDXSetupButtonProdProdIdent)).enabled(prodParmStartUp.NDXPrintProdProdIdent == NoYes::Yes);
}
